def password(name, en, fr, desc_en=None, desc_fr=None):
    # osd:password: masked in the UI and in Data Services
    f = F(name, en=en, fr=fr, desc_en=desc_en, desc_fr=desc_fr, maxLen=4000)  # encrypted form of a long token (OpenAI sk-proj-...) exceeds 255
    f.type = 'password'
    # the default osd:password editor stores a SHA-512 hash (one way): declare EBX's reversible encryption
    # so that the module can read the secret back (com.on.ebx.connect.core.Secrets)
    f.encryptionClass = 'com.orchestranetworks.security.PasswordTypeEncryption'
    return f

# patch the emitter with the password type
import extend_xsd
extend_xsd.XS['password'] = 'osd:password'

