    out = [HEADER]
    for t in TABLES:
        out.append('\n'.join(table(t, ' ' * 16)))
    out.append(FOOTER)
    text = '\n'.join(out)
    import xml.etree.ElementTree as ET
    ET.fromstring(text.encode('utf-8'))
    open(OUT, 'w', encoding='utf-8').write(text)
    print('written', OUT, text.count('\n'), 'lines')
